{
  "implementation": "def solve(case):
    threshold = case['threshold']
    calls = case['calls']
    accepted_call_ids = []
    diagnostics = []
    for call in calls:
        gain = call['loss_without_call'] - call['loss_with_call']
        tokens = call['prediction_tokens']
        if tokens < 1:
            tokens = 1
        normalized_gain = gain / tokens
        is_accepted = call['parseable'] and normalized_gain >= threshold
        if is_accepted:
            accepted_call_ids.append(call['call_id'])
        diagnostics.append({
            'accepted': is_accepted,
            'call_id': call['call_id'],
            'normalized_gain': round(normalized_gain, 6)
        })
    return {
        'accepted_call_ids': accepted_call_ids,
        'diagnostics': diagnostics
    }"
}
